/**
 * Concurrency verification runner for Owner Auto-Pause and Carryover Debt Gate.
 *
 * Requirements:
 * - TEST_DATABASE_URL is the ONLY accepted target; never fall back to DATABASE_URL.
 * - If TEST_DATABASE_URL is not set, report UNRUN/SKIPPED rather than falsely reporting PASS.
 * - Single parameterized SQL statements per query (no multi-statement queries in pg extended protocol).
 * - Complete, proven ready fixtures: valid slot 2, sealed predecessor checkpoint, met=true, debt=0.
 * - Case 1: Concurrent duplicate resume on the SAME campaign -> exactly 1 success + 1 CAMPAIGN_NOT_PAUSED.
 * - Case 2: Concurrent resume on TWO DIFFERENT campaigns of same owner -> both succeed, tests not double-subtracted.
 * - Fail on deadlocks or unexpected errors.
 *
 * Usage:
 *   $env:TEST_DATABASE_URL="postgresql://postgres:postgres@localhost:5432/postgres"
 *   node supabase/tests/run-owner-auto-pause-concurrency-test.mjs
 */

import crypto from 'node:crypto';
import assert from 'node:assert/strict';

const databaseUrl = process.env.TEST_DATABASE_URL;

if (!databaseUrl) {
  console.log('========================================================================');
  console.log('NOTICE: TEST_DATABASE_URL is not set.');
  console.log('Skipping multi-connection PostgreSQL concurrency test (UNRUN/SKIPPED).');
  console.log('To run this test against a disposable PostgreSQL test instance:');
  console.log('  export TEST_DATABASE_URL="postgresql://postgres:postgres@localhost:5432/postgres"');
  console.log('  node supabase/tests/run-owner-auto-pause-concurrency-test.mjs');
  console.log('========================================================================');
  process.exit(0);
}

const { default: pg } = await import('pg');
const { Pool } = pg;
const pool = new Pool({ connectionString: databaseUrl, max: 10, statement_timeout: 10000 });

const runId = crypto.randomUUID().replace(/-/g, '').substring(0, 8);
const ownerId = crypto.randomUUID();
const adminId = crypto.randomUUID();
const supplierId = crypto.randomUUID();
const camp1 = crypto.randomUUID();
const camp2 = crypto.randomUUID();
const supplyCamp = crypto.randomUUID();

console.log(`=== RUNNING MULTI-CONNECTION OWNER RESUME CONCURRENCY TEST (Run: ${runId}) ===`);

async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}

async function runAs(client, userId, sql, params = []) {
  await client.query('BEGIN');
  try {
    await client.query(`SELECT set_config('request.jwt.claim.sub', $1, true)`, [userId]);
    await client.query(`SET LOCAL ROLE authenticated`);
    const res = await client.query(sql, params);
    await client.query('COMMIT');
    return res;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  }
}

try {
  // Setup fixture using individual single parameterized statements
  await withClient(async client => {
    await client.query(`INSERT INTO auth.users (id, email) VALUES ($1, $2) ON CONFLICT (id) DO NOTHING`, [adminId, `admin-${runId}@test.invalid`]);
    await client.query(`INSERT INTO auth.users (id, email) VALUES ($1, $2) ON CONFLICT (id) DO NOTHING`, [supplierId, `supplier-${runId}@test.invalid`]);
    await client.query(`INSERT INTO auth.users (id, email) VALUES ($1, $2) ON CONFLICT (id) DO NOTHING`, [ownerId, `owner-${runId}@test.invalid`]);

    await client.query(`UPDATE public.profiles SET role = 'admin', is_locked = false, credits = 1000 WHERE id = $1`, [adminId]);
    await client.query(`UPDATE public.profiles SET role = 'moderator', is_locked = false, credits = 1000 WHERE id = $1`, [supplierId]);
    await client.query(`UPDATE public.profiles SET role = 'member', is_locked = false, credits = 1000 WHERE id = $1`, [ownerId]);

    // Slot 2 for owner
    await client.query(`INSERT INTO public.user_slots (user_id, slot_number, expires_at) VALUES ($1, 2, NOW() + interval '30 days') ON CONFLICT DO NOTHING`, [ownerId]);

    // Supplier open app
    await client.query(`INSERT INTO public.campaigns (id, owner_id, app_name, package_name, status, slot_number, created_at) VALUES ($1, $2, 'Supply App', 'com.supply.app', 'open', 1, NOW() - interval '15 days') ON CONFLICT (id) DO UPDATE SET status = 'open'`, [supplyCamp, supplierId]);

    // Owner campaigns (initially paused with owner_inactive)
    await client.query(`INSERT INTO public.campaigns (id, owner_id, app_name, package_name, status, paused_reason, slot_number, created_at) VALUES ($1, $2, 'Concur App 1', 'com.concur.app1', 'paused', 'owner_inactive', 1, NOW() - interval '15 days') ON CONFLICT (id) DO UPDATE SET status = 'paused', paused_reason = 'owner_inactive'`, [camp1, ownerId]);
    await client.query(`INSERT INTO public.campaigns (id, owner_id, app_name, package_name, status, paused_reason, slot_number, created_at) VALUES ($1, $2, 'Concur App 2', 'com.concur.app2', 'paused', 'owner_inactive', 2, NOW() - interval '15 days') ON CONFLICT (id) DO UPDATE SET status = 'paused', paused_reason = 'owner_inactive'`, [camp2, ownerId]);

    // Finalize yesterday's checkpoint with zero debt and streak 0
    await client.query(`
      INSERT INTO public.user_daily_tasks (user_id, task_date, mode, finalized_at, missed_streak, carry_out_tests, met, base_required_tests, carry_in_tests)
      VALUES ($1, (NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date - 1, 'owner', NOW(), 0, 0, true, 3, 0)
      ON CONFLICT (user_id, task_date) DO UPDATE SET finalized_at = NOW(), missed_streak = 0, carry_out_tests = 0, met = true;
    `, [ownerId]);
    await client.query(`UPDATE public.profiles SET daily_missed_streak = 0 WHERE id = $1`, [ownerId]);

    // Record qualifying test today so met=true and debt=0
    await client.query(`
      INSERT INTO public.daily_test_events_journal (source_type, source_id, user_id, campaign_id, campaign_owner_id, activity_date, status, is_qualifying, observed_at)
      VALUES ('checkin', gen_random_uuid(), $1, $2, $3, (NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date, 'valid', true, NOW())
    `, [ownerId, supplyCamp, supplierId]);
  });

  // CASE 1: Concurrent duplicate resume on SAME campaign (camp1)
  console.log('--- Case 1: Concurrent duplicate resume on SAME campaign (camp1) ---');
  const results1 = await Promise.allSettled([
    withClient(client => runAs(client, ownerId, 'SELECT public.resume_campaign($1) as r', [camp1])),
    withClient(client => runAs(client, ownerId, 'SELECT public.resume_campaign($1) as r', [camp1])),
  ]);

  const fulfilled1 = results1.filter(r => r.status === 'fulfilled');
  const rejected1 = results1.filter(r => r.status === 'rejected');

  assert.equal(fulfilled1.length, 1, 'Exactly one concurrent call on the same campaign must succeed');
  assert.equal(fulfilled1[0].value.rows[0].r.status, 'open', 'Succeeded call must return status open');

  assert.equal(rejected1.length, 1, 'The losing concurrent call must be rejected');
  assert.match(rejected1[0].reason.message, /CAMPAIGN_NOT_PAUSED/, 'Losing concurrent call must see CAMPAIGN_NOT_PAUSED');
  console.log('PASS: Case 1 - Exactly 1 succeeded (open) and 1 rejected (CAMPAIGN_NOT_PAUSED), no deadlocks');

  // CASE 2: Concurrent resume on TWO DIFFERENT campaigns of same owner (camp1 & camp2)
  console.log('--- Case 2: Concurrent resume on TWO DIFFERENT campaigns (camp1 & camp2) ---');
  // Reset both to paused for case 2
  await withClient(async client => {
    await client.query(`UPDATE public.campaigns SET status = 'paused', paused_reason = 'owner_inactive' WHERE id IN ($1, $2)`, [camp1, camp2]);
  });

  const results2 = await Promise.allSettled([
    withClient(client => runAs(client, ownerId, 'SELECT public.resume_campaign($1) as r', [camp1])),
    withClient(client => runAs(client, ownerId, 'SELECT public.resume_campaign($1) as r', [camp2])),
  ]);

  const fulfilled2 = results2.filter(r => r.status === 'fulfilled');
  const rejected2 = results2.filter(r => r.status === 'rejected');

  assert.equal(fulfilled2.length, 2, 'Both independent campaigns of the owner must resume successfully');
  assert.equal(rejected2.length, 0, 'No unexpected rejections or deadlocks when resuming distinct campaigns');
  assert.equal(fulfilled2[0].value.rows[0].r.status, 'open');
  assert.equal(fulfilled2[1].value.rows[0].r.status, 'open');

  // Verify debt was not double-subtracted
  await withClient(async client => {
    const debtCheck = await client.query(`SELECT public.get_daily_task_status($1, (NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) as s`, [ownerId]);
    const s = debtCheck.rows[0].s;
    assert.equal(s.carryover_remaining_tests, 0, 'Remaining debt remains 0 and tests are not double-subtracted');
  });
  console.log('PASS: Case 2 - Both distinct campaigns resumed concurrently with zero debt and no double subtraction');

  console.log('\n=== ALL CONCURRENCY PROBES PASSED SUCCESSFULLY ===');
} finally {
  await withClient(async client => {
    await client.query(`DELETE FROM public.campaigns WHERE id IN ($1, $2, $3)`, [camp1, camp2, supplyCamp]).catch(() => {});
    await client.query(`DELETE FROM public.user_daily_tasks WHERE user_id = $1`, [ownerId]).catch(() => {});
    await client.query(`DELETE FROM public.daily_test_events_journal WHERE user_id = $1`, [ownerId]).catch(() => {});
    await client.query(`DELETE FROM public.user_slots WHERE user_id = $1`, [ownerId]).catch(() => {});
    await client.query(`DELETE FROM public.profiles WHERE id IN ($1, $2, $3)`, [ownerId, adminId, supplierId]).catch(() => {});
    await client.query(`DELETE FROM auth.users WHERE id IN ($1, $2, $3)`, [ownerId, adminId, supplierId]).catch(() => {});
  }).catch(() => {});
  await pool.end();
}

